update public.books set metadata=jsonb_set(metadata,'{chapterOneReview}',(metadata->'chapterOneReview') || jsonb_build_object('date','2026-11-06','status','partial','pending',(select coalesce(jsonb_agg(item),'[]'::jsonb) from jsonb_array_elements(metadata->'chapterOneReview'->'pending') item where item->>'id' not in ('ship','lalouette')),'publishedNewReferences',(select jsonb_agg(value order by value) from (select distinct value from jsonb_array_elements(coalesce(metadata->'chapterOneReview'->'publishedNewReferences','[]'::jsonb) || '["ship","lalouette"]'::jsonb)) ids),'addressResolution','{"date":"2026-11-06","ids":["ship","lalouette"],"precision":"Ship: modern civic address matched to historical map. Lalouette: area of replacement college complex, not original building.","records":"research/ulisse-chapter-1/addresses-records.json"}'::jsonb)) where id='ulisse';
