select p.id,p.latitude,p.longitude,r.category,e.language,jsonb_array_length(b.metadata->'chapterOneReview'->'pending') as remaining_pending from public.places p join public.place_references r on r.book_id=p.book_id and r.place_id=p.id join public.excerpts e on e.book_id=r.book_id and e.reference_id=r.id join public.books b on b.id=p.book_id where p.book_id='ulisse' and r.section_id=1 and p.id in ('ship','lalouette') order by p.id;
