insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,additional_source_id,metadata) values ('ulisse','ship','core','The Ship','5 Lower Abbey Street · Dublin','historical',16,'2026-11-06','Historical site reference','The Ship was a hotel and tavern at 5 Lower Abbey Street. At the end of the episode Mulligan arranges to meet Stephen there at half past twelve.','Historical address 5 Lower Abbey Street established by Gunn, Hart and Beck, James Joyce’s Dublin, map 12 (PDF page 44), and Irish Genealogy. Position is the published coordinate of the modern civic address, corroborated against the guide’s street map; approximate reference for the historical plot, not a surveyed coordinate or a claim that the original tavern survives.','1a173577c05f7d47047968489a9361dd8c367cb87b1acfe5dea7d8b3fb300a88','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','479736fe1ef6f92af3538fae0d43a0c49a5a11fa4832ee2a4a50604880d11fdd','{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"it":"The Ship era un albergo e una taverna al 5 di Lower Abbey Street. Alla fine dell’episodio Mulligan vi dà appuntamento a Stephen per mezzogiorno e mezzo.","en":"The Ship was a hotel and tavern at 5 Lower Abbey Street. At the end of the episode Mulligan arranges to meet Stephen there at half past twelve.","fr":"The Ship était un hôtel et une taverne au 5 Lower Abbey Street. À la fin de l’épisode, Mulligan y donne rendez-vous à Stephen à midi et demi.","es":"The Ship era un hotel y una taberna en el número 5 de Lower Abbey Street. Al final del episodio Mulligan cita allí a Stephen a las doce y media."}},"positionPrecision":{"type":"historical-site-reference","basis":"Modern civic address matched to a historical topographical map","originalCoordinate":[53.3486704,-6.2587275],"originalBuildingSurvival":"Not established"},"additionalSources":["https://www.irishgenealogy.ie/2016-family-history/learning-resources/sean-mac-diarmada.html","https://www.revenue.ie/en/corporate/documents/statistics/excise/register-of-bookmaking-offices.pdf"]}'::jsonb) on conflict do nothing;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','1:core:ship',1,'ship','core',15,'mentioned','The Ship was a hotel and tavern at 5 Lower Abbey Street. At the end of the episode Mulligan arranges to meet Stephen there at half past twelve.','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','{"explicitCategory":true,"narrativeDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"it":"The Ship era un albergo e una taverna al 5 di Lower Abbey Street. Alla fine dell’episodio Mulligan vi dà appuntamento a Stephen per mezzogiorno e mezzo.","en":"The Ship was a hotel and tavern at 5 Lower Abbey Street. At the end of the episode Mulligan arranges to meet Stephen there at half past twelve.","fr":"The Ship était un hôtel et une taverne au 5 Lower Abbey Street. À la fin de l’épisode, Mulligan y donne rendez-vous à Stephen à midi et demi.","es":"The Ship era un hotel y una taberna en el número 5 de Lower Abbey Street. Al final del episodio Mulligan cita allí a Stephen a las doce y media."}},"categoryReason":"Future rendezvous proposed from the bathing place; no scene at the tavern in episode I."}'::jsonb) on conflict do nothing;
