insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,additional_source_id,metadata) values ('ulisse','lalouette','core','Lalouette’s','68 Marlborough Street · Dublin','historical',16,'2026-11-06','Historical site reference','Lalouette’s was the funeral establishment at 68 Marlborough Street that Mulligan evokes while speaking of Stephen’s mourning. Its historical site lies within the area of the College of Catering, built in 1938–39.','Thom’s 1904 directory and the contemporary Lalouette advertisement identify 68 Marlborough Street. Dublin City Council’s 2005–2011 RPS, entry 5119, places no. 68 in the College of Catering site (66–72 Marlborough Street). NIAH 50010236 dates the replacement college to 1938–39. Current DCC RPS CSV entry 1331 locates that compound at Irish Grid E315949.03 N234923.958; transformed from EPSG:29903 to EPSG:4326 with pyproj, yielding 53.3520579375438,-6.259480078764796. Approximate reference to the replacement complex containing the historical site, not the footprint or entrance of the lost no. 68 building.','1a19b012dacf37a3014ee95c47bb7635bf63782409509bac466acb94bce2a329','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','089aea1288f7fe75d52a22cc5f4680ecf625e124d7d6f41f8a3fac1fc91b8a34','{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"it":"Lalouette’s era l’impresa funebre al 68 di Marlborough Street evocata da Mulligan parlando del lutto di Stephen. Il sito storico si trova nell’area del College of Catering, costruito nel 1938–39.","en":"Lalouette’s was the funeral establishment at 68 Marlborough Street that Mulligan evokes while speaking of Stephen’s mourning. Its historical site lies within the area of the College of Catering, built in 1938–39.","fr":"Lalouette’s était l’entreprise de pompes funèbres du 68 Marlborough Street évoquée par Mulligan à propos du deuil de Stephen. Son emplacement historique se trouve dans l’enceinte du College of Catering, construit en 1938–39.","es":"Lalouette’s era la funeraria del número 68 de Marlborough Street que Mulligan evoca al hablar del duelo de Stephen. Su emplazamiento histórico se encuentra en el recinto del College of Catering, construido en 1938–39."}},"positionPrecision":{"type":"historical-site-area","basis":"Later college complex containing the former numbered plots; original individual plot not separately surveyed","originalBuildingSurvival":"Replaced by the college built in 1938–39","sourceRecord":"Dublin City Council RPS 1331","sourceCrs":"EPSG:29903","sourceEasting":315949.03,"sourceNorthing":234923.958,"targetCrs":"EPSG:4326","unroundedCoordinate":[53.3520579375438,-6.259480078764796]},"additionalSources":["https://conor-mccabe.com/wp-content/uploads/2023/01/thoms-1904-street-directory.pdf","https://james-joyce.ru/ulysses/LastPink.pdf","https://www.dublincity.ie/sites/default/files/2026-01/volume-3.pdf","https://www.riverrun.org.uk/JJD2_Small.pdf"]}'::jsonb) on conflict do nothing;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','1:core:lalouette',1,'lalouette','core',16,'mentioned','Lalouette’s was the funeral establishment at 68 Marlborough Street that Mulligan evokes while speaking of Stephen’s mourning. Its historical site lies within the area of the College of Catering, built in 1938–39.','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','{"explicitCategory":true,"narrativeDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"it":"Lalouette’s era l’impresa funebre al 68 di Marlborough Street evocata da Mulligan parlando del lutto di Stephen. Il sito storico si trova nell’area del College of Catering, costruito nel 1938–39.","en":"Lalouette’s was the funeral establishment at 68 Marlborough Street that Mulligan evokes while speaking of Stephen’s mourning. Its historical site lies within the area of the College of Catering, built in 1938–39.","fr":"Lalouette’s était l’entreprise de pompes funèbres du 68 Marlborough Street évoquée par Mulligan à propos du deuil de Stephen. Son emplacement historique se trouve dans l’enceinte du College of Catering, construit en 1938–39.","es":"Lalouette’s era la funeraria del número 68 de Marlborough Street que Mulligan evoca al hablar del duelo de Stephen. Su emplazamiento histórico se encuentra en el recinto del College of Catering, construido en 1938–39."}},"categoryReason":"Funeral establishment invoked in a comparison; no scene at its premises."}'::jsonb) on conflict do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','1:core:lalouette:original',1,'1:core:lalouette','original','en','original','You crossed her last wish in death and yet you sulk with me because I don’t whinge like some hired mute from Lalouette’s. Absurd! I suppose I did say it. I didn’t mean to offend the memory of your mother.','James Joyce · Ulysses · Shakespeare and Company, Paris, 1922 · Chapter I','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["Lalouette’s"],"reviewedAt":"2026-11-06","translationReview":{"it":"No verified reusable version located; see chapterOneReview and research report","fr":"No verified reusable version located; see chapterOneReview and research report","es":"No verified reusable version located; see chapterOneReview and research report"}}'::jsonb) on conflict do nothing;
